update public.learning_paths
set
  title = 'Derivatives and Risk Management',
  goal = 'Derivatives and Risk Management',
  summary = 'This course develops the theory, market practice, and governance of derivative instruments and financial risk management. Students learn how forwards, futures, options, swaps, credit derivatives, and structured products are priced and used, while also learning how market, credit, liquidity, operational, model, and enterprise risks are measured and controlled.',
  data = $drmjson${"slug": "derivatives-and-risk-management", "title": "Derivatives and Risk Management", "description": "This course develops the theory, market practice, and governance of derivative instruments and financial risk management. Students learn how forwards, futures, options, swaps, credit derivatives, and structured products are priced and used, while also learning how market, credit, liquidity, operational, model, and enterprise risks are measured and controlled.", "topics": [{"id": "9c64831e-34b7-4330-9386-0c27b27636f6", "type": "topic", "title": "Derivative Markets, Instruments, and Risk Transfer", "description": "Students learn why derivatives exist, how organized and OTC markets work, and how contracts move risk between participants.", "children": [{"id": "997cbad2-78aa-4cad-b9a2-e053503a9555", "type": "subtopic", "title": "Market purpose and participants", "children": [{"id": "117b0e43-3fe3-4fcf-a622-ef02e6b589ab", "type": "concept", "title": "Hedgers, speculators, arbitrageurs, dealers, and market makers"}, {"id": "0febafd5-4a87-41d6-b17d-cb3ff6a6bf74", "type": "concept", "title": "Exchange-traded versus OTC derivatives"}, {"id": "9107022f-1778-4576-8908-2482fb5dfdd1", "type": "concept", "title": "Risk transfer, price discovery, leverage, and liquidity"}], "description": "The point is to understand derivatives as risk-transfer contracts, not isolated formulas."}, {"id": "322e3fb6-c93a-49df-8945-6c87053683b2", "type": "subtopic", "title": "Instrument taxonomy", "children": [{"id": "46bf275b-7444-43c7-9ff0-656bd01c3853", "type": "concept", "title": "Forwards, futures, swaps, options, and credit derivatives"}, {"id": "a80fb540-ee7d-4c9c-a607-35e0c03f6136", "type": "concept", "title": "Equity, rate, FX, commodity, and credit underlyings"}, {"id": "f88e2438-c557-4f07-841d-dcc3e059d898", "type": "concept", "title": "Linear versus nonlinear payoff profiles"}], "description": "Students build a map of the major derivative families before pricing them."}, {"id": "19db596f-7c76-4df7-94b0-0bb1ec24c664", "type": "subtopic", "title": "Institutional market structure", "children": [{"id": "377c3b3e-5a44-450e-985d-3d73b3f99e8a", "type": "concept", "title": "Exchanges, clearinghouses, brokers, and swap dealers"}, {"id": "46e7237b-b807-4278-9a14-46420da6ce65", "type": "concept", "title": "ISDA agreements and confirmations"}, {"id": "9a02ee6f-4405-4d16-9aba-5c5368b4c9e8", "type": "concept", "title": "Margin, settlement, and lifecycle events"}], "description": "Real derivative risk depends on trading venues, documentation, and settlement mechanics."}]}, {"id": "5e654f99-7ebd-46bd-8f35-a1a83276c7b2", "type": "topic", "title": "Forwards and Futures: Mechanics, Pricing, and Basis Risk", "description": "This module builds the no-arbitrage logic for forward and futures prices and connects it to real hedging practice.", "children": [{"id": "e266c109-8e81-49d8-9db2-bc95251ae655", "type": "subtopic", "title": "Contract mechanics", "children": [{"id": "e3c93635-5a8b-4c75-adf3-01573f937eff", "type": "concept", "title": "Delivery, cash settlement, contract size, and expiration"}, {"id": "ddf78e96-f8c5-43ee-94cf-33afecf76928", "type": "concept", "title": "Daily marking to market and margin calls"}, {"id": "aa89aa9a-0187-4e04-b9f2-df9bc9ee5271", "type": "concept", "title": "Open interest, volume, and roll conventions"}], "description": "Students learn the operational differences that drive valuation and risk."}, {"id": "0223bb11-2ce2-4afd-b8cd-26d388dcbd6b", "type": "subtopic", "title": "No-arbitrage pricing", "children": [{"id": "06855977-56a1-45ac-96e7-3ab22979bb9d", "type": "concept", "title": "Spot-forward parity"}, {"id": "e2b4a817-a41c-4f6d-b0e8-e5d276b9bd57", "type": "concept", "title": "Cost of carry, storage, convenience yield, and dividends"}, {"id": "b8399245-29a5-4820-8a39-9c6f673b9650", "type": "concept", "title": "Currency forwards and interest-rate parity"}], "description": "Forward pricing teaches the core logic used throughout derivatives."}, {"id": "4e0cc89f-2ec1-49d5-9d0a-3433c1050661", "type": "subtopic", "title": "Basis risk", "children": [{"id": "7cab3bf0-1f8a-4dc0-9fca-8501113dca3b", "type": "concept", "title": "Spot-futures basis and convergence"}, {"id": "81b86da4-7fa2-431c-a89d-0026b4ef23e5", "type": "concept", "title": "Cross-hedging and proxy hedges"}, {"id": "b8b254ec-31db-477f-aa82-ff49ae4de116", "type": "concept", "title": "Calendar basis and roll yield"}], "description": "Hedges fail when the hedge instrument and exposure do not move identically."}]}, {"id": "aff8d9e1-9315-4b57-a9dd-462d722458de", "type": "topic", "title": "Hedging with Futures, Forwards, and Commodity Contracts", "description": "Students learn how firms, investors, and institutions design hedge programs and evaluate hedge effectiveness.", "children": [{"id": "214725a5-f656-4264-84ab-6c95b724ecb7", "type": "subtopic", "title": "Hedge design", "children": [{"id": "1c9f39bf-5c84-4caf-85d9-6ec620f9cac7", "type": "concept", "title": "Short and long hedges"}, {"id": "ddd5cc87-46cb-4c35-9f22-469eaf10fb18", "type": "concept", "title": "Minimum-variance hedge ratio"}, {"id": "2d181ac0-72cc-425d-a0d8-e7e312db842a", "type": "concept", "title": "Hedge horizon and contract selection"}], "description": "Students learn to translate an exposure into a defensible hedge ratio and implementation plan."}, {"id": "f36c4fd1-35fa-44b2-a80c-64304bf39dad", "type": "subtopic", "title": "Commodity and FX hedging", "children": [{"id": "3f477201-e20c-433f-895a-57be08bb63e8", "type": "concept", "title": "Fuel, metals, agriculture, and energy hedges"}, {"id": "3bbd7dc6-6d3c-47f1-94c7-44ca68136a26", "type": "concept", "title": "Foreign-currency receivables and payables"}, {"id": "b0b5b141-0ba5-40db-9e1c-955a445d1d4f", "type": "concept", "title": "Natural hedges versus financial hedges"}], "description": "Applied hedging shows how finance interacts with operations, procurement, and treasury."}, {"id": "a1b7ff4b-72df-452c-a947-426a436e932b", "type": "subtopic", "title": "Hedge evaluation", "children": [{"id": "1cc46d39-9468-4ab8-bf2c-7cfd6a3c4b5b", "type": "concept", "title": "Ex ante hedge objectives"}, {"id": "f7a82938-53ed-4270-b0a2-357c5d4015a0", "type": "concept", "title": "Ex post hedge effectiveness"}, {"id": "ad58e620-1b07-4ac8-b0c4-fc250e586502", "type": "concept", "title": "Cash-flow, fair-value, and economic hedges"}], "description": "A hedge is judged by risk reduction, economics, accounting, and governance."}]}, {"id": "738c697e-1569-49cd-be4b-052d8ae05b29", "type": "topic", "title": "Options Fundamentals, Payoffs, and Trading Strategies", "description": "This topic develops option vocabulary, payoff geometry, and the economic intuition behind nonlinear exposures.", "children": [{"id": "c887a4be-23b5-4d6b-8a1f-3a2581827865", "type": "subtopic", "title": "Option language and payoffs", "children": [{"id": "d2c66639-3764-4f05-a409-dfd43b46e31a", "type": "concept", "title": "Calls, puts, moneyness, intrinsic value, and time value"}, {"id": "a36556d6-fa15-4711-93d3-0d06fe3217f0", "type": "concept", "title": "Long and short payoff diagrams"}, {"id": "c696cda7-8114-4ca9-a6dd-4bcd9c4cb3f5", "type": "concept", "title": "Put-call parity"}], "description": "The aim is to make nonlinear risk visible before moving into pricing models."}, {"id": "4a3e7a4d-ddc9-4a6d-a6a6-be462ef6cae5", "type": "subtopic", "title": "Strategy construction", "children": [{"id": "499b86b0-31ab-4aa7-bd82-4e5aa65d03cb", "type": "concept", "title": "Covered calls, protective puts, collars, and spreads"}, {"id": "5aa9ae1d-483a-47ce-ab1f-ebbf1de2aaba", "type": "concept", "title": "Straddles, strangles, butterflies, and condors"}, {"id": "c8e18adc-261e-441f-9be1-af3d810ff799", "type": "concept", "title": "Risk-reward diagrams and breakeven analysis"}], "description": "Strategies show how options combine to express views on direction, volatility, and tails."}, {"id": "bd2bdbe7-3928-47e9-bb62-05a5698146a6", "type": "subtopic", "title": "Economic uses", "children": [{"id": "1ab63c30-1139-4ec8-ae38-acc10a24f10d", "type": "concept", "title": "Portfolio insurance"}, {"id": "4b5fb023-11c3-43c6-adfd-94cf3bd8f714", "type": "concept", "title": "Employee stock options and warrants"}, {"id": "cb3669c2-f785-40c0-a707-97521a9a0125", "type": "concept", "title": "Real options in staged investment decisions"}], "description": "Students connect option structures to investment, corporate, and risk-management problems."}]}, {"id": "349c76b8-9000-47e8-a6f1-b8cdfde38b31", "type": "topic", "title": "Binomial Option Pricing and Risk-Neutral Valuation", "description": "Students learn a discrete-time pricing model that makes replication, arbitrage, and risk-neutral valuation concrete.", "children": [{"id": "97d5ad7b-9ced-49e8-8fad-d45826103235", "type": "subtopic", "title": "One-period replication", "children": [{"id": "02f66901-047e-47d0-bb78-1b4e249ae619", "type": "concept", "title": "Up and down states"}, {"id": "b5c8219c-060a-4044-b341-17d570af6adc", "type": "concept", "title": "Hedge ratio"}, {"id": "77b3dce0-655d-4f3b-8c3f-4cef3ed5d2f2", "type": "concept", "title": "No-arbitrage bounds"}], "description": "Replication reveals why derivative prices are pinned down by hedging rather than by investor preference."}, {"id": "aa8177a2-a40c-41bb-83a7-63c5c2b6a9df", "type": "subtopic", "title": "Multi-period trees", "children": [{"id": "129759c1-9d8f-4ec3-bc41-2f689dbf42f5", "type": "concept", "title": "Recombining trees"}, {"id": "db3a2cfd-fc76-4ad4-97a7-b8c1e1d65cf7", "type": "concept", "title": "Early exercise and American options"}, {"id": "4e9f53b8-ae8d-4be0-b727-ef276fe34a22", "type": "concept", "title": "Dividends and path dependence"}], "description": "Trees provide an intuitive bridge from simple replication to realistic valuation."}, {"id": "6a0f5968-6f47-476d-95dd-a38017247f84", "type": "subtopic", "title": "Risk-neutral valuation", "children": [{"id": "d38652fb-488e-43a4-89b1-b698a31ece8f", "type": "concept", "title": "Risk-neutral probabilities"}, {"id": "62f4ff50-437c-4431-bf64-3f61f987d08b", "type": "concept", "title": "Discounted expected payoff"}, {"id": "100fca7a-adc4-4793-8e0b-c8920078ae8f", "type": "concept", "title": "Relationship to real-world probabilities"}], "description": "Students learn the pricing measure that underlies most modern derivative models."}]}, {"id": "5aa67a0f-e471-4699-806a-6073ec671825", "type": "topic", "title": "Black-Scholes-Merton, Greeks, and Dynamic Hedging", "description": "This module develops the canonical continuous-time option model and the risk sensitivities used to manage option books.", "children": [{"id": "09746569-20f7-4100-aafc-fb45ca1c5814", "type": "subtopic", "title": "Model assumptions and formula intuition", "children": [{"id": "0b9f0ff0-f675-4e59-93e0-b29d97890429", "type": "concept", "title": "Lognormal prices and continuous trading"}, {"id": "bd029fc0-36ca-44ae-a22b-0c246fdf0743", "type": "concept", "title": "Constant volatility and frictionless markets"}, {"id": "5d72b705-8143-4911-9661-b387708e542d", "type": "concept", "title": "European call and put valuation"}], "description": "Students learn what Black-Scholes-Merton explains and where its assumptions are fragile."}, {"id": "ee7c3551-e029-40fa-8daa-9e21b26ef70b", "type": "subtopic", "title": "Greeks", "children": [{"id": "70ec8800-c6b1-4559-a2bd-31359453d2ec", "type": "concept", "title": "Delta, gamma, vega, theta, and rho"}, {"id": "16f583d4-e256-4761-8103-336702d0e8aa", "type": "concept", "title": "Second-order and cross-Greeks"}, {"id": "c9bef5e1-b111-493a-9af4-8d0cceeae1a2", "type": "concept", "title": "Portfolio-level sensitivities"}], "description": "Greeks are the operating language for option risk management."}, {"id": "f402e4f6-c35c-4f8e-8603-e6af57eb7b5e", "type": "subtopic", "title": "Dynamic hedging", "children": [{"id": "181679a8-e39d-48a8-a9f5-b411951aab5a", "type": "concept", "title": "Delta hedging and rebalancing"}, {"id": "f705d0a7-d6f0-4d54-88d8-a0b49e36537d", "type": "concept", "title": "Gamma risk and transaction costs"}, {"id": "e4e1431c-8af1-4c7f-8da9-4c960cde24b1", "type": "concept", "title": "Hedging errors under jumps and volatility changes"}], "description": "Students see how option replication becomes a trading and operational problem."}]}, {"id": "bc0868b1-c679-4e56-b61f-4356e76fd3ab", "type": "topic", "title": "Volatility, Implied Volatility Surfaces, and Advanced Option Risk", "description": "Students move beyond textbook Black-Scholes assumptions toward volatility smiles, skew, term structure, and model limitations.", "children": [{"id": "796f5822-7970-41bd-ab59-20c623f4b837", "type": "subtopic", "title": "Volatility concepts", "children": [{"id": "9504ee05-d6ed-4934-b648-1a98f2bd9f8b", "type": "concept", "title": "Realized, historical, implied, and forecast volatility"}, {"id": "9abeb4b0-17e4-4f45-a1ef-077d2e93160a", "type": "concept", "title": "Volatility clustering"}, {"id": "e83b3169-e18d-4e33-8792-e06d5e558c4b", "type": "concept", "title": "Volatility risk premium"}], "description": "The gist is that volatility is both an input, an estimate, and a traded object."}, {"id": "ffc06b6d-e98a-49d2-af80-fc133a3cbccf", "type": "subtopic", "title": "Smile and surface behavior", "children": [{"id": "db6f866f-1374-44cf-8a5a-e5019aa00115", "type": "concept", "title": "Skew, smile, term structure, and moneyness"}, {"id": "47aa5d37-6d7a-4a65-a1c4-06de3e99fe94", "type": "concept", "title": "Equity-index versus FX and commodity smiles"}, {"id": "d4b847dc-3132-4283-a1e8-4a6b6ef317e4", "type": "concept", "title": "Surface interpolation and arbitrage checks"}], "description": "Market option prices reveal deviations from the simplest model."}, {"id": "60eb310f-207f-44e9-a022-167275033061", "type": "subtopic", "title": "Advanced option risk", "children": [{"id": "5534a298-7b98-4c3c-8a31-eb26d5d11da7", "type": "concept", "title": "Local volatility, stochastic volatility, and jump intuition"}, {"id": "a265d73e-87cf-477f-ad6b-abb4f33b8bde", "type": "concept", "title": "Exotics and path-dependent payoffs"}, {"id": "fee9c4e1-9f2f-4095-ae9c-787349206669", "type": "concept", "title": "VIX and volatility derivatives overview"}], "description": "Students learn why model choice and tail assumptions matter."}]}, {"id": "57c9839a-123d-4e0f-afb3-cc876be43b2d", "type": "topic", "title": "Swaps, Interest Rate Derivatives, and Fixed Income Risk", "description": "This topic links swaps and rates derivatives to yield curves, duration, convexity, and institutional balance-sheet risk.", "children": [{"id": "128d8114-6ab4-48fd-87f1-764f0d96ba64", "type": "subtopic", "title": "Swap mechanics and pricing", "children": [{"id": "fc4033cc-bde8-4030-8245-42d452514a33", "type": "concept", "title": "Plain-vanilla interest rate swaps"}, {"id": "d720a423-9f3c-4bcb-99be-70a93ede506c", "type": "concept", "title": "Currency swaps and total return swaps"}, {"id": "e832da9a-2217-426e-abe6-51a129a83fde", "type": "concept", "title": "Swap rate, fixed leg, floating leg, and netting"}], "description": "Swaps make interest-rate, currency, and cash-flow risk transferable."}, {"id": "84f7b12f-12fa-4d4e-84c6-dab67e1ff090", "type": "subtopic", "title": "Yield curve and rate risk", "children": [{"id": "8cf45740-1aac-4f29-9730-ce1acf21144a", "type": "concept", "title": "Zero rates, forward rates, and curve bootstrapping"}, {"id": "0a90b81e-9df2-4c39-8533-b54e6601e00a", "type": "concept", "title": "Duration, convexity, and key-rate duration"}, {"id": "aeba26b3-13e7-42a1-9a13-dc17dcb3c37c", "type": "concept", "title": "Term structure and spread risk"}], "description": "Rates derivatives require a strong fixed-income foundation."}, {"id": "5bb9a1c5-7e80-4808-8dc9-59b631b3b754", "type": "subtopic", "title": "Rate derivatives applications", "children": [{"id": "83da5450-6fcc-4ea2-8709-fd1a1aadcf32", "type": "concept", "title": "FRAs, caps, floors, and swaptions"}, {"id": "41a03a8b-ff14-472c-886c-463bf3dd3d82", "type": "concept", "title": "Asset-liability management"}, {"id": "5a8fdbc2-795c-432d-b96d-b5aaa1f4a1b7", "type": "concept", "title": "Mortgage and callable-bond optionality"}], "description": "Students connect derivatives to bank, corporate, and asset-management use cases."}]}, {"id": "b9684dd7-9690-4090-8ee0-a926d7875a4e", "type": "topic", "title": "Credit Risk, Credit Derivatives, and Structured Products", "description": "Students learn how default risk is measured, transferred, priced, and amplified through credit-sensitive instruments.", "children": [{"id": "7dafefd9-a2fa-44ff-99a0-e9a002661fa4", "type": "subtopic", "title": "Credit-risk foundations", "children": [{"id": "1b233598-e000-409d-b987-49c2efb2a833", "type": "concept", "title": "Probability of default, loss given default, and exposure at default"}, {"id": "83e012d8-8d0b-4bd1-9524-2aeaef4b4733", "type": "concept", "title": "Credit ratings and migration"}, {"id": "b4b8e97c-b21f-4ea7-b7ee-57aa0b8aa1b7", "type": "concept", "title": "Credit spreads and default intensity intuition"}], "description": "Credit risk turns default probability and loss severity into measurable financial exposure."}, {"id": "d187e938-d41e-4dd0-b72c-9397ac2aeb21", "type": "subtopic", "title": "Credit derivatives", "children": [{"id": "a4b933a9-69a0-4e52-a294-da5d8681995a", "type": "concept", "title": "Credit default swaps"}, {"id": "7551e6f4-4326-4ada-8322-355474df9fdd", "type": "concept", "title": "Total return swaps"}, {"id": "9770801d-b5f6-4532-a9e3-cd886f4167cb", "type": "concept", "title": "CDS spreads, upfronts, and settlement"}], "description": "Students learn how default risk is transferred and priced."}, {"id": "a9659f08-6794-44fd-a7ca-673e5dca8351", "type": "subtopic", "title": "Structured products", "children": [{"id": "e7e681c2-457f-4ae0-b6e7-1a99b04e3522", "type": "concept", "title": "Securitization and tranching"}, {"id": "7116a121-80fe-4725-b405-08871474b9f7", "type": "concept", "title": "ABS, MBS, and CDO overview"}, {"id": "87abd646-50f3-45f6-9868-e760b358c4b1", "type": "concept", "title": "Correlation, waterfall risk, and crisis lessons"}], "description": "Structured credit shows how cash-flow priority can transform, but not eliminate, risk."}]}, {"id": "fde394bd-cf7b-41e3-8342-16bc5763f14c", "type": "topic", "title": "Counterparty Risk, Collateral, Clearing, and Valuation Adjustments", "description": "This module covers the modern post-crisis infrastructure for OTC derivatives, XVA, margining, and counterparty exposure.", "children": [{"id": "4719f1d0-a0e1-454f-8874-6103c5062203", "type": "subtopic", "title": "Counterparty exposure", "children": [{"id": "87f591a8-f5d0-4774-b5ea-c4bce0cc193e", "type": "concept", "title": "Current exposure and potential future exposure"}, {"id": "faad6043-85af-46d4-8cbc-2324144f21be", "type": "concept", "title": "Netting sets and closeout"}, {"id": "4c6b56c8-caea-42e8-864d-7135f043502a", "type": "concept", "title": "Wrong-way risk"}], "description": "Derivative valuation is incomplete without default exposure to the trading counterparty."}, {"id": "bc7ef805-9480-42e8-9a85-6736d34095dd", "type": "subtopic", "title": "Collateral and clearing", "children": [{"id": "f55c04fb-3100-4cc4-8727-c8b39177aa3c", "type": "concept", "title": "Initial margin and variation margin"}, {"id": "86cdb8f8-9241-480e-8d0c-98dda0f7aeb8", "type": "concept", "title": "Central clearing and clearinghouse risk"}, {"id": "9f9c912e-4bc7-4415-9a3a-0580a74a5ea2", "type": "concept", "title": "Uncleared margin rules"}], "description": "Post-crisis market design changed how OTC derivative risk is controlled."}, {"id": "829c500c-821b-4542-b28a-c216f9f66fbb", "type": "subtopic", "title": "Valuation adjustments", "children": [{"id": "49b0063d-e723-4e3d-aedd-772ce4f3ac70", "type": "concept", "title": "CVA, DVA, FVA, MVA, and KVA intuition"}, {"id": "077669b8-0710-4ee6-a866-a12fa0902bf9", "type": "concept", "title": "Collateral discounting and OIS curves"}, {"id": "4070e128-f565-46e0-834a-6667cedf7867", "type": "concept", "title": "XVA governance and desk-level implications"}], "description": "XVA connects pricing to funding, credit, collateral, and capital."}]}, {"id": "24760ca7-69a4-4959-a451-f912966fbe1f", "type": "topic", "title": "Market Risk Measurement: VaR, Expected Shortfall, and Scenario Analysis", "description": "Students learn the statistical toolkit used to measure losses under normal and stressed market conditions.", "children": [{"id": "04d2ce2f-617d-4209-99bb-f55bf83075cb", "type": "subtopic", "title": "Value at Risk", "children": [{"id": "5ab3dff7-9902-4814-bf2d-7002f47f7d6f", "type": "concept", "title": "Holding period and confidence level"}, {"id": "c1851892-bff5-4b7d-a8a0-15073475a328", "type": "concept", "title": "Historical, variance-covariance, and Monte Carlo VaR"}, {"id": "c54a3f43-e13b-4abb-9df2-171f53180fdb", "type": "concept", "title": "Backtesting exceptions"}], "description": "VaR summarizes a loss quantile, but students must know exactly what it hides."}, {"id": "3b6cafa2-c513-4c7f-91ef-a4fbe928ef8a", "type": "subtopic", "title": "Expected shortfall", "children": [{"id": "f7334b54-e618-4c5e-b5aa-490052598834", "type": "concept", "title": "Tail conditional expectation"}, {"id": "49576b1a-1e11-40e8-a5fd-5991825c457d", "type": "concept", "title": "Coherence and subadditivity"}, {"id": "57786a5a-31b3-4e54-92da-7a4eb431acb6", "type": "concept", "title": "Basel market-risk context"}], "description": "Expected shortfall focuses attention on tail losses beyond the VaR threshold."}, {"id": "5c4450d6-7263-4f17-9fc7-93970152c0c1", "type": "subtopic", "title": "Scenario analysis", "children": [{"id": "a84df2b6-ac42-43e2-b687-f8edbbbc64aa", "type": "concept", "title": "Historical crisis scenarios"}, {"id": "b83e109e-a780-40ee-8fda-137d9e517f8b", "type": "concept", "title": "Hypothetical shocks"}, {"id": "c6b1a235-44ae-486f-b345-64bfb1b651f2", "type": "concept", "title": "Sensitivity, reverse stress tests, and dashboards"}], "description": "Scenarios make risk measurement intelligible to decision-makers."}]}, {"id": "59b0029b-0f2d-44b4-82fe-1251c7c01515", "type": "topic", "title": "Stress Testing, Liquidity Risk, Operational Risk, and Model Risk", "description": "This topic expands risk management beyond price moves to the failures that often dominate real crises.", "children": [{"id": "834718ed-857f-4c3a-8c9e-7d968daa56a9", "type": "subtopic", "title": "Stress testing", "children": [{"id": "43da37c0-5d1e-4da8-8789-7847037e1064", "type": "concept", "title": "Macro, market, and idiosyncratic scenarios"}, {"id": "1655fe7e-9379-4fd8-9c8b-d9d607f5b639", "type": "concept", "title": "CCAR/DFAST-style thinking"}, {"id": "67fa1d2c-464c-421c-9550-144a06be5bf9", "type": "concept", "title": "Capital planning and contingency actions"}], "description": "Stress tests ask what breaks when assumptions, correlations, and liquidity deteriorate together."}, {"id": "8a21bf0d-dcd9-42b3-979c-7b2f40200b86", "type": "subtopic", "title": "Liquidity and funding risk", "children": [{"id": "390c76bd-f286-4bd6-a9ae-78d67114fec5", "type": "concept", "title": "Market liquidity versus funding liquidity"}, {"id": "37ab300a-cefe-4bff-aba7-ccc55cfb3d98", "type": "concept", "title": "Haircuts, margin spirals, and fire sales"}, {"id": "4cdf9af0-9970-447d-b208-2ca90d9e48ef", "type": "concept", "title": "Liquidity-adjusted valuation and limits"}], "description": "A position can be theoretically solvent and practically dangerous if it cannot be funded or exited."}, {"id": "893a4ddc-5345-4c58-a0eb-8ee3f32986c7", "type": "subtopic", "title": "Operational and model risk", "children": [{"id": "4a0d2200-397d-45b6-9504-981c8e0f9082", "type": "concept", "title": "Trade capture, settlement, and control failures"}, {"id": "99f2082d-1be0-4aba-9f3c-2aa1f44486f2", "type": "concept", "title": "Model validation and independent review"}, {"id": "6a556b49-ada3-468b-98fe-3da6b2879489", "type": "concept", "title": "Limitations, assumptions, and challenger models"}], "description": "Many losses come from people, process, systems, data, and models rather than market direction."}]}, {"id": "059e382f-d25f-44eb-a8f3-1ff748593414", "type": "topic", "title": "Enterprise Risk Management, Governance, Regulation, and Ethics", "description": "Students connect technical models to limits, reporting, risk culture, professional standards, and regulatory capital.", "children": [{"id": "dc5f2b1c-13ee-45fb-a191-6ba3ccecefda", "type": "subtopic", "title": "Risk appetite and limits", "children": [{"id": "3c8594ef-5003-4a70-bf48-1b8d84d494bd", "type": "concept", "title": "Risk appetite statements"}, {"id": "e396a2e5-00a5-4d41-b3fa-e4f47c130967", "type": "concept", "title": "Limit design, escalation, and breaches"}, {"id": "6e498447-cf8d-4e27-9bfc-4d17c5dfd8db", "type": "concept", "title": "Board, CRO, treasury, and trading-desk roles"}], "description": "Risk management becomes effective only when technical measures govern real decisions."}, {"id": "3263713c-f904-40da-887c-d835cac67fda", "type": "subtopic", "title": "Regulation and capital", "children": [{"id": "85726ade-92d6-4328-80af-daa1cc3fea1e", "type": "concept", "title": "Basel capital and liquidity standards"}, {"id": "aa210a0a-1fe5-42c4-80b3-249efc48c81c", "type": "concept", "title": "Dodd-Frank, EMIR, clearing, and reporting"}, {"id": "6737868a-7ed5-4a6b-9bc8-12b0be1ed2c8", "type": "concept", "title": "Accounting and hedge documentation overview"}], "description": "Students learn the rules shaping derivatives, banks, and risk reporting."}, {"id": "fbbb79ce-205c-45d9-bda4-6aabc94b741f", "type": "subtopic", "title": "Ethics and risk culture", "children": [{"id": "a8bcc17e-9085-4714-b9f8-44c71aeebc04", "type": "concept", "title": "Speculation versus hedging"}, {"id": "a76cd0b2-1fa0-44e8-95b0-025aaf7633ad", "type": "concept", "title": "Conflicts of interest and client suitability"}, {"id": "48ce4563-b980-47f9-a607-ffbc0b458454", "type": "concept", "title": "Lessons from Barings, LTCM, AIG, JPMorgan London Whale, and Archegos"}], "description": "The course treats misuse, opacity, and incentives as central, not peripheral."}]}, {"id": "b039324c-aac1-4616-b3df-bedc1a864997", "type": "topic", "title": "Risk Analytics Lab: Data, Python or Excel, and Model Validation", "description": "The course provides practical depth when students implement models, interrogate data, and test assumptions themselves.", "children": [{"id": "5b619282-4968-41a2-b5ec-fedf73be3b94", "type": "subtopic", "title": "Data and implementation", "children": [{"id": "60a25884-d8a2-48fb-b9d2-e7fcdfafa77e", "type": "concept", "title": "Market data, yields, prices, volatilities, and returns"}, {"id": "9b33022b-324a-40ff-a0b2-0d85679aac65", "type": "concept", "title": "Excel implementation discipline"}, {"id": "964df507-c60f-4ab2-9d2e-ca81a4c3c5a6", "type": "concept", "title": "Python notebooks with pandas, NumPy, SciPy, and QuantLib awareness"}], "description": "Students should be able to reproduce pricing and risk numbers, not only describe them."}, {"id": "986f9611-8e64-46cf-a2f4-3481cea9409d", "type": "subtopic", "title": "Pricing and risk analytics", "children": [{"id": "e1e000bd-1fcb-467c-b6f9-b94d65602d55", "type": "concept", "title": "Forward and futures pricing calculators"}, {"id": "b8b11ecc-5e8a-4d68-85c2-57e2f567b7c8", "type": "concept", "title": "Binomial and Black-Scholes option pricers"}, {"id": "cb2865f3-a50d-4cb4-93d8-8e5a5456caac", "type": "concept", "title": "Delta hedging simulation and P&L attribution"}], "description": "Hands-on models reveal the assumptions hidden in closed-form formulas."}, {"id": "0af69fee-d0db-43db-b381-2d9264cf2392", "type": "subtopic", "title": "Validation and communication", "children": [{"id": "a9d0fe26-2cd7-4e69-ad44-eb45a76bc297", "type": "concept", "title": "Unit tests and benchmark cases"}, {"id": "8e23ddc7-ead6-4d02-9ac6-4316ffe982b8", "type": "concept", "title": "Sensitivity analysis and error checks"}, {"id": "a51cb495-6163-4853-92ed-cb3151adbb5e", "type": "concept", "title": "Clear risk reports, charts, and model limitations"}], "description": "The lab trains students to challenge model outputs and explain uncertainty."}]}, {"id": "63b0d018-cbed-4faf-8930-ab9a14759404", "type": "topic", "title": "Integrated Hedging and Risk Management Capstone", "description": "Students synthesize pricing, hedging, risk measurement, governance, and communication in a professional risk memo.", "children": [{"id": "404c192d-5000-4786-8e08-f16d00838fdd", "type": "subtopic", "title": "Case selection", "children": [{"id": "a40958de-4cb5-4288-b3a3-e2ce7cc0074e", "type": "concept", "title": "Corporate FX, commodity, rate, or equity exposure"}, {"id": "248fefdf-eb89-4429-b7c5-70fd8014dd67", "type": "concept", "title": "Investment portfolio downside risk"}, {"id": "18a19a0b-d15d-437b-aa3f-23427e19bba2", "type": "concept", "title": "Financial institution balance-sheet risk"}], "description": "Students choose a realistic exposure and define the decision problem."}, {"id": "5ee79faf-1759-47d7-a843-d4f24073e485", "type": "subtopic", "title": "Analysis and hedge proposal", "children": [{"id": "a41660cf-fa73-454f-95da-17ccddcdd348", "type": "concept", "title": "Exposure diagnosis"}, {"id": "7009aa40-4aa1-47ac-ba1c-e55716427078", "type": "concept", "title": "Instrument comparison and hedge ratio"}, {"id": "fd2c6f14-c559-41b2-9e0a-63f26abfe14b", "type": "concept", "title": "Pricing, Greeks, VaR, stress tests, and liquidity constraints"}], "description": "The capstone requires a defensible link between instruments, model outputs, and risk objectives."}, {"id": "82cda0bc-9bec-4991-afb5-a4300f2c5494", "type": "subtopic", "title": "Professional risk memo", "children": [{"id": "4fed30f3-de39-4582-a36b-10c4ae61ed65", "type": "concept", "title": "Recommendation and tradeoffs"}, {"id": "683246d8-5321-4682-9974-e79c3785889b", "type": "concept", "title": "Governance, accounting, and operational controls"}, {"id": "621209ad-beb0-45d7-86d4-956ffe2516db", "type": "concept", "title": "Residual risk, monitoring plan, and escalation triggers"}], "description": "The final deliverable should read like work product for a CFO, CRO, investment committee, or regulator."}]}], "dbBacked": true}$drmjson$::jsonb,
